-- 1. Ensure Table Exists (Safe CREATE TABLE IF NOT EXISTS)
CREATE TABLE IF NOT EXISTS `CurriculumLessons` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `owner` int(11) NOT NULL DEFAULT 1,
  `learningLanguage` varchar(10) NOT NULL DEFAULT 'de',
  `nativeLanguage` varchar(10) NOT NULL DEFAULT 'en',
  `level` enum('A1','A2','B1','B2','C1','C2') NOT NULL DEFAULT 'A1',
  `unitNumber` int(11) NOT NULL DEFAULT 1,
  `unitTitle` varchar(200) NOT NULL DEFAULT 'Coral Reef',
  `unitDescription` varchar(300) DEFAULT 'Introductions & Daily Greetings',
  `lessonIndex` int(11) NOT NULL DEFAULT 0,
  `title` varchar(200) NOT NULL,
  `subtitle` varchar(300) DEFAULT '',
  `nodeType` enum('lesson','karaoke','speech','chest','match','quiz','boss') NOT NULL DEFAULT 'lesson',
  `xpReward` int(11) DEFAULT 15,
  `pearlsReward` int(11) DEFAULT 5,
  `isLive` tinyint(1) NOT NULL DEFAULT 1,
  `stages` longtext,
  `karaokeData` longtext,
  `audioUrl` varchar(500) DEFAULT NULL,
  `sourceNoteId` int(11) DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. Clean existing seed if re-running (optional safeguard)
-- DELETE FROM `CurriculumLessons` WHERE `learningLanguage` = 'de' AND `level` = 'A1';

-- 3. Insert German A1 Lessons (Units 1 & 2)
INSERT INTO `CurriculumLessons` (`owner`, `learningLanguage`, `nativeLanguage`, `level`, `unitNumber`, `unitTitle`, `unitDescription`, `lessonIndex`, `title`, `subtitle`, `nodeType`, `xpReward`, `pearlsReward`, `isLive`, `stages`, `karaokeData`, `audioUrl`, `createdAt`, `updatedAt`) VALUES (1, 'de', 'en', 'A1', 1, 'Coral Reef', 'Erste Schritte: Basic Greetings & Introductions', 0, 'Hallo & Guten Tag', 'Essential German greetings & daily etiquette', 'lesson', 15, 5, 1, '[{"type":"word_match","title":"Match the word pairs","pairs":[{"target":"Guten Morgen","native":"Good morning"},{"target":"Guten Tag","native":"Hello / Good day"},{"target":"Danke","native":"Thank you"},{"target":"Bitte","native":"Please / You are welcome"},{"target":"Tschüss","native":"Bye"}]},{"type":"listen_tap","title":"Listen and tap what you hear","targetSentence":"Guten Morgen! Danke schön.","tokens":["Guten","Morgen!","Danke","schön.","Kaffee","Tee"],"audioUrl":""},{"type":"sentence_builder","title":"Construct the German sentence","prompt":"Translate: Hello, thank you very much!","targetSentence":"Guten Tag, vielen Dank!","tokens":["Guten","Tag,","vielen","Dank!","Tschüss","Bitte"]},{"type":"sprechen","title":"Pronounce Auf Deutsch","prompt":"Guten Tag! Wie geht es dir?","translation":"Hello! How are you?","minAccuracy":75,"audioUrl":""}]', NULL, NULL, NOW(), NOW());

INSERT INTO `CurriculumLessons` (`owner`, `learningLanguage`, `nativeLanguage`, `level`, `unitNumber`, `unitTitle`, `unitDescription`, `lessonIndex`, `title`, `subtitle`, `nodeType`, `xpReward`, `pearlsReward`, `isLive`, `stages`, `karaokeData`, `audioUrl`, `createdAt`, `updatedAt`) VALUES (1, 'de', 'en', 'A1', 1, 'Coral Reef', 'Erste Schritte: Basic Greetings & Introductions', 1, 'Ich heiße...', 'Introducing yourself & asking names', 'lesson', 15, 5, 1, '[{"type":"word_match","title":"Match the word pairs","pairs":[{"target":"Ich heiße","native":"My name is"},{"target":"Wie heißt du?","native":"What is your name?"},{"target":"Wer bist du?","native":"Who are you?"},{"target":"Freut mich","native":"Nice to meet you"}]},{"type":"listen_tap","title":"Listen and tap what you hear","targetSentence":"Hallo, ich heiße Lukas.","tokens":["Hallo,","ich","heiße","Lukas.","wer","bist"],"audioUrl":""},{"type":"sentence_builder","title":"Construct the German sentence","prompt":"Translate: Who are you? My name is Anna.","targetSentence":"Wer bist du? Ich heiße Anna.","tokens":["Wer","bist","du?","Ich","heiße","Anna.","Guten","Morgen"]},{"type":"sprechen","title":"Pronounce Auf Deutsch","prompt":"Freut mich, dich kennenzulernen!","translation":"Pleased to meet you!","minAccuracy":75,"audioUrl":""}]', NULL, NULL, NOW(), NOW());

INSERT INTO `CurriculumLessons` (`owner`, `learningLanguage`, `nativeLanguage`, `level`, `unitNumber`, `unitTitle`, `unitDescription`, `lessonIndex`, `title`, `subtitle`, `nodeType`, `xpReward`, `pearlsReward`, `isLive`, `stages`, `karaokeData`, `audioUrl`, `createdAt`, `updatedAt`) VALUES (1, 'de', 'en', 'A1', 1, 'Coral Reef', 'Erste Schritte: Basic Greetings & Introductions', 2, 'Woher kommst du?', 'Countries, origins and where you live', 'lesson', 15, 5, 1, '[{"type":"word_match","title":"Match the word pairs","pairs":[{"target":"Deutschland","native":"Germany"},{"target":"Indien","native":"India"},{"target":"kommen aus","native":"to come from"},{"target":"wohnen in","native":"to live in"}]},{"type":"listen_tap","title":"Listen and tap what you hear","targetSentence":"Ich komme aus Deutschland.","tokens":["Ich","komme","aus","Deutschland.","wohne","Indien"],"audioUrl":""},{"type":"sentence_builder","title":"Construct the German sentence","prompt":"Translate: Where do you come from? I come from India.","targetSentence":"Woher kommst du? Ich komme aus Indien.","tokens":["Woher","kommst","du?","Ich","komme","aus","Indien.","heiße"]},{"type":"sprechen","title":"Pronounce Auf Deutsch","prompt":"Ich komme aus Indien und wohne hier.","translation":"I come from India and live here.","minAccuracy":75,"audioUrl":""}]', NULL, NULL, NOW(), NOW());

INSERT INTO `CurriculumLessons` (`owner`, `learningLanguage`, `nativeLanguage`, `level`, `unitNumber`, `unitTitle`, `unitDescription`, `lessonIndex`, `title`, `subtitle`, `nodeType`, `xpReward`, `pearlsReward`, `isLive`, `stages`, `karaokeData`, `audioUrl`, `createdAt`, `updatedAt`) VALUES (1, 'de', 'en', 'A1', 1, 'Coral Reef', 'Erste Schritte: Basic Greetings & Introductions', 3, 'Audio Karaoke Rhythm', 'Das erste Treffen - Synced dialog', 'karaoke', 25, 10, 1, '[{"type":"karaoke","title":"Audio Karaoke Rhythm","storyText":"Guten Tag! Ich heiße Florian. Und wer bist du? Hallo Florian, ich heiße Meera. Ich komme aus Indien. Schön, dich kennenzulernen!","translationText":"Good day! My name is Florian. And who are you? Hello Florian, my name is Meera. I come from India. Nice to meet you!"}]', NULL, NULL, NOW(), NOW());

