INSERT INTO `CurriculumLessons` (`owner`, `learningLanguage`, `nativeLanguage`, `level`, `unitNumber`, `unitTitle`, `unitDescription`, `lessonIndex`, `title`, `subtitle`, `nodeType`, `xpReward`, `pearlsReward`, `isLive`, `stages`, `karaokeData`, `audioUrl`, `createdAt`, `updatedAt`) VALUES (1, 'de', 'en', 'A1', 1, 'Coral Reef', 'Erste Schritte: Basic Greetings & Introductions', 5, 'Coral Reef Exam', 'Mastery challenge to clear Unit 1', 'lesson', 35, 15, 1, '[{"type":"word_match","title":"Speed Review","pairs":[{"target":"Guten Tag","native":"Hello"},{"target":"Danke","native":"Thank you"},{"target":"Tschüss","native":"Bye"},{"target":"Deutschland","native":"Germany"}]},{"type":"sentence_builder","title":"Unit 1 Final Challenge","prompt":"Translate: Hello, how are you today?","targetSentence":"Hallo, wie geht es dir heute?","tokens":["Hallo,","wie","geht","es","dir","heute?","Morgen","Kaffee"]},{"type":"sprechen","title":"Unit 1 Final Pronunciation","prompt":"Guten Abend! Ich heiße Florian und komme aus Berlin.","translation":"Good evening! My name is Florian and I come from Berlin.","minAccuracy":80,"audioUrl":""}]', NULL, NULL, NOW(), NOW());

INSERT INTO `CurriculumLessons` (`owner`, `learningLanguage`, `nativeLanguage`, `level`, `unitNumber`, `unitTitle`, `unitDescription`, `lessonIndex`, `title`, `subtitle`, `nodeType`, `xpReward`, `pearlsReward`, `isLive`, `stages`, `karaokeData`, `audioUrl`, `createdAt`, `updatedAt`) VALUES (1, 'de', 'en', 'A1', 2, 'Emerald Bay', 'Im Café & Zahlen 0–20: Ordering drinks & counting', 6, 'Was möchten Sie trinken?', 'Ordering coffee, tea and water in German', 'lesson', 15, 5, 1, '[{"type":"word_match","title":"Match the café pairs","pairs":[{"target":"der Kaffee","native":"the coffee"},{"target":"der Tee","native":"the tea"},{"target":"das Wasser","native":"the water"},{"target":"die Milch","native":"the milk"},{"target":"Ich möchte","native":"I would like"}]},{"type":"listen_tap","title":"Listen and tap what you hear","targetSentence":"Ich möchte einen Kaffee, bitte.","tokens":["Ich","möchte","einen","Kaffee,","bitte.","Tee","Milch"],"audioUrl":""},{"type":"sentence_builder","title":"Construct the German sentence","prompt":"Translate: A water with milk, please.","targetSentence":"Ein Wasser mit Milch, bitte.","tokens":["Ein","Wasser","mit","Milch,","bitte.","Kaffee","Guten","Tag"]},{"type":"sprechen","title":"Pronounce Auf Deutsch","prompt":"Einen Tee mit Zucker, bitte.","translation":"A tea with sugar, please.","minAccuracy":75,"audioUrl":""}]', NULL, NULL, NOW(), NOW());

INSERT INTO `CurriculumLessons` (`owner`, `learningLanguage`, `nativeLanguage`, `level`, `unitNumber`, `unitTitle`, `unitDescription`, `lessonIndex`, `title`, `subtitle`, `nodeType`, `xpReward`, `pearlsReward`, `isLive`, `stages`, `karaokeData`, `audioUrl`, `createdAt`, `updatedAt`) VALUES (1, 'de', 'en', 'A1', 2, 'Emerald Bay', 'Im Café & Zahlen 0–20: Ordering drinks & counting', 7, 'Zahlen 0 bis 10', 'Counting drinks and orders', 'lesson', 15, 5, 1, '[{"type":"word_match","title":"Match the numbers","pairs":[{"target":"eins, zwei","native":"one, two"},{"target":"drei, vier","native":"three, four"},{"target":"fünf, sechs","native":"five, six"},{"target":"sieben, acht","native":"seven, eight"},{"target":"neun, zehn","native":"nine, ten"}]},{"type":"listen_tap","title":"Listen and tap what you hear","targetSentence":"Zwei Kaffee und drei Tee, bitte.","tokens":["Zwei","Kaffee","und","drei","Tee,","bitte.","vier","Wasser"],"audioUrl":""},{"type":"sentence_builder","title":"Construct the German sentence","prompt":"Translate: I would like five waters, please.","targetSentence":"Ich möchte fünf Wasser, bitte.","tokens":["Ich","möchte","fünf","Wasser,","bitte.","sechs","Danke"]},{"type":"sprechen","title":"Pronounce Auf Deutsch","prompt":"Bitte zwei Kaffee und ein Wasser.","translation":"Two coffees and one water, please.","minAccuracy":75,"audioUrl":""}]', NULL, NULL, NOW(), NOW());

INSERT INTO `CurriculumLessons` (`owner`, `learningLanguage`, `nativeLanguage`, `level`, `unitNumber`, `unitTitle`, `unitDescription`, `lessonIndex`, `title`, `subtitle`, `nodeType`, `xpReward`, `pearlsReward`, `isLive`, `stages`, `karaokeData`, `audioUrl`, `createdAt`, `updatedAt`) VALUES (1, 'de', 'en', 'A1', 2, 'Emerald Bay', 'Im Café & Zahlen 0–20: Ordering drinks & counting', 8, 'Die Rechnung & Zahlen 11–20', 'Asking for the bill and paying in Euros', 'lesson', 15, 5, 1, '[{"type":"word_match","title":"Match the payment terms","pairs":[{"target":"die Rechnung","native":"the bill"},{"target":"Was kostet das?","native":"How much does that cost?"},{"target":"Euro","native":"Euro"},{"target":"zwölf","native":"twelve"},{"target":"zwanzig","native":"twenty"}]},{"type":"listen_tap","title":"Listen and tap what you hear","targetSentence":"Das macht zusammen zwölf Euro.","tokens":["Das","macht","zusammen","zwölf","Euro.","zehn","Kaffee"],"audioUrl":""},{"type":"sentence_builder","title":"Construct the German sentence","prompt":"Translate: The bill, please! That costs four euros.","targetSentence":"Die Rechnung, bitte! Das kostet vier Euro.","tokens":["Die","Rechnung,","bitte!","Das","kostet","vier","Euro.","Wasser"]},{"type":"sprechen","title":"Pronounce Auf Deutsch","prompt":"Zahlen, bitte! Wir möchten bezahlen.","translation":"Check, please! We would like to pay.","minAccuracy":75,"audioUrl":""}]', NULL, NULL, NOW(), NOW());

